import org.junit.*;import static org.junit.Assert.*;import com.fasterxml.jackson.databind.*;
public class SupplementalFunctionalTest {
 @BeforeClass public static void start()throws Exception{FullFunctionalTest.setup();FullFunctionalTest.sql("insert ignore into campus_merchant_sequence(id,seq) values(1,1000)");}@AfterClass public static void stop()throws Exception{FullFunctionalTest.close();}
 @Before public void login()throws Exception{FullFunctionalTest.cookie="";FullFunctionalTest.ok(FullFunctionalTest.post("/login","username=testadmin&password=Test2026ok&rememberMe=false"));}
 @Test public void merchantCreateQueryAndDisable()throws Exception{String token=FullFunctionalTest.variable(FullFunctionalTest.get("/campus/merchant"),"token");JsonNode category=FullFunctionalTest.post("/campus/merchant/category",FullFunctionalTest.form("name","JUnit类型"+System.nanoTime(),"token",token));assertTrue(category.toString(),category.has("code"));JsonNode saved=FullFunctionalTest.post("/campus/merchant/save",FullFunctionalTest.form("name","JUnit新增商户","category",category.path("code").asText(),"contact","测试联系人","phone","13800000004","address","测试校区","owner_name","测试负责人","owner_phone","13800000005","token",token));assertTrue(saved.toString(),saved.has("id"));long id=saved.path("id").asLong();assertTrue(FullFunctionalTest.get("/campus/merchant/search?name=JUnit").contains("JUnit新增商户"));assertTrue(FullFunctionalTest.post("/campus/merchant/status",FullFunctionalTest.form("id",""+id,"active","0","reason","测试停用","token",token)).path("ok").asBoolean());assertEquals(0,FullFunctionalTest.scalar("select active from campus_merchant where id="+id));}
 @Test public void financeInternalReconciliationAndBatchQuery()throws Exception{String token=FullFunctionalTest.variable(FullFunctionalTest.get("/campus/finance"),"token");assertTrue(FullFunctionalTest.get("/campus/finance/overview?start=2026-11-01&end=2026-11-05").startsWith("{"));JsonNode r=FullFunctionalTest.post("/campus/finance/internal",FullFunctionalTest.form("start","2026-11-01","end","2026-11-05","token",token));assertTrue(r.toString(),r.has("batchId"));String batch=r.path("batchId").asText();assertTrue(FullFunctionalTest.get("/campus/finance/batches?page=1").contains(batch));assertTrue(FullFunctionalTest.get("/campus/finance/lines?batch="+batch).startsWith("{"));}
 @Test public void roleCreateGrantBindAndAudit()throws Exception{String token=FullFunctionalTest.variable(FullFunctionalTest.get("/system/permission"),"token");JsonNode role=FullFunctionalTest.post("/system/permission/role",FullFunctionalTest.form("name","JUnit测试角色"+System.nanoTime(),"key","junit_"+System.nanoTime(),"status","0","token",token));assertTrue(role.toString(),role.has("id"));String id=role.path("id").asText();assertTrue(FullFunctionalTest.post("/system/permission/grant",FullFunctionalTest.form("role",id,"ids","8100100","token",token)).path("ok").asBoolean());assertTrue(FullFunctionalTest.post("/system/permission/bind",FullFunctionalTest.form("user","880002","roles",id,"token",token)).path("ok").asBoolean());assertTrue(FullFunctionalTest.get("/system/permission/userRoles?user=880002").contains(id));assertTrue(FullFunctionalTest.get("/system/permission/audit").contains("GRANT"));}
}


